package it.vintedaffari.app;
/** Current listing state by observed signature; read-only, not a chronological conversion funnel. */
final class ObservationFunnelSql {
    static String rows(){return "SELECT signature,reason FROM (SELECT o.signature, CASE WHEN l.id IS NULL THEN 'NO_CANONICAL' WHEN COALESCE(l.lifecycle,'UNKNOWN') NOT IN ('ACTIVE','AUTO_FILTERED') THEN CASE l.lifecycle WHEN 'SOLD' THEN 'INACTIVE_SOLD' WHEN 'REMOVED' THEN 'INACTIVE_REMOVED' WHEN 'USER_HIDDEN' THEN 'INACTIVE_USER_HIDDEN' WHEN 'UNKNOWN' THEN 'INACTIVE_UNKNOWN' ELSE CASE WHEN l.lifecycle IS NULL THEN 'INACTIVE_UNKNOWN' ELSE 'INACTIVE_OTHER' END END WHEN l.enrichment_state='AUTO_EXCLUDED' THEN 'AUTO_EXCLUDED' WHEN l.lifecycle='AUTO_FILTERED' OR l.enrichment_state='AUTO_FILTERED' THEN 'AUTO_FILTERED' WHEN l.enrichment_state='BLOCKED_CLASSIFIER' THEN 'CLASSIFIER_BLOCKED' WHEN l.enrichment_state='PENDING_ANALYSIS' THEN 'ANALYSIS_PENDING' WHEN g.id IS NULL THEN 'GAME_MISSING' WHEN COALESCE(g.match_state,'')<>'MATCHED' OR COALESCE(g.bgg_id,'')='' THEN 'BGG_UNRESOLVED' WHEN g.rating IS NULL THEN 'RATING_PENDING' WHEN g.rating<6.0 THEN 'BELOW_RATING' WHEN COALESCE(g.database_visible,0)<>1 THEN 'GAME_HIDDEN' ELSE 'BGG_QUALIFIED' END AS reason FROM (SELECT DISTINCT signature FROM observations WHERE observed_at>=? AND observed_at<=?) o LEFT JOIN market_listings l ON l.id=(SELECT MIN(x.id) FROM market_listings x WHERE (x.legacy_signature=o.signature AND x.legacy_signature<>'') OR ((x.legacy_signature IS NULL OR x.legacy_signature='') AND x.temp_fingerprint=o.signature)) LEFT JOIN games g ON g.id=l.game_id) ORDER BY signature";}
}
